import{_ as s,a0 as l,w as p,s as h,ao as i,I as o,x as t,a1 as r,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"OnionShare：匿名共享文件 | LCTT x X-CMD","titleTemplate":false,"description":"OnionShare：匿名共享文件 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"OnionShare：匿名共享文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"OnionShare：匿名共享文件 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171208 OnionShare - Share Files Anonymously","title":"OnionShare：匿名共享文件","tag":"201712","desc":""},"relativePath":"201712/20171208 OnionShare - Share Files Anonymously.md","filePath":"[post].md"}'),d={name:"201712/20171208 OnionShare - Share Files Anonymously.md"};function u(f,n,w,m,S,g){const e=l("Link");return p(),h("div",null,[n[22]||(n[22]=i('<h1 id="onionshare-匿名共享文件" tabindex="-1">OnionShare：匿名共享文件 <a class="header-anchor" href="#onionshare-匿名共享文件" aria-label="Permalink to “OnionShare：匿名共享文件”">​</a></h1><p><img src="http://www.theitstuff.com/wp-content/uploads/2017/12/OnionShare-Share-Files-Anonymously.jpg" alt=""></p><p>在這個數字世界中，我們通過互聯網使用 Dropbox、Mega、Google Drive 等不同雲存儲分享我們的媒體、文檔和重要文件。但是每個雲存儲都有兩個主要問題，一個是大小和另一個安全。習慣 Bit Torrent 之後，大小已經不是問題了，但安全性仍舊是。</p><p>你即使通過安全的雲服務發送文件，該公司也會注意到這些文件，如果這些文件是保密的，政府甚至可以拿到它們。因此，為了克服這些問題，我們使用 OnionShare，如它的名字那樣它使用洋葱網絡也就是 Tor 來匿名分享文件給任何人。</p><h3 id="如何使用-onionshare" tabindex="-1">如何使用 <strong>OnionShare</strong>？ <a class="header-anchor" href="#如何使用-onionshare" aria-label="Permalink to “如何使用 OnionShare？”">​</a></h3>',5)),o("p",null,[n[2]||(n[2]=t("首先下載 ",-1)),r(e,{href:"https://onionshare.org/"},{default:a(()=>[...n[0]||(n[0]=[t("OnionShare",-1)])]),_:1}),n[3]||(n[3]=t(" 和 ",-1)),r(e,{href:"https://www.torproject.org/projects/torbrowser.html.en"},{default:a(()=>[...n[1]||(n[1]=[t("Tor瀏覽器",-1)])]),_:1}),n[4]||(n[4]=t("。下載後安裝它們。",-1))]),o("p",null,[r(e,{href:"http://www.theitstuff.com/wp-content/uploads/2017/12/Icons.png"},{default:a(()=>[...n[5]||(n[5]=[o("img",{src:"http://www.theitstuff.com/wp-content/uploads/2017/12/Icons.png",alt:"install onionshare and tor browser"},null,-1)])]),_:1})]),n[23]||(n[23]=o("p",null,"現在從開始菜單打開 OnionShare",-1)),o("p",null,[r(e,{href:"http://www.theitstuff.com/wp-content/uploads/2017/12/Onion-Share.png"},{default:a(()=>[...n[6]||(n[6]=[o("img",{src:"http://www.theitstuff.com/wp-content/uploads/2017/12/Onion-Share.png",alt:"onionshare share files anonymously"},null,-1)])]),_:1})]),n[24]||(n[24]=o("p",null,"點擊添加並添加一個文件/文件夾共享。",-1)),n[25]||(n[25]=o("p",null,"點擊開始分享。它會產生一個 .onion 網址，你可以與你的收件人分享這個網址。",-1)),o("p",null,[r(e,{href:"http://www.theitstuff.com/wp-content/uploads/2017/12/With-Link.png"},{default:a(()=>[...n[7]||(n[7]=[o("img",{src:"http://www.theitstuff.com/wp-content/uploads/2017/12/With-Link.png",alt:"share file with onionshare anonymously"},null,-1)])]),_:1})]),n[26]||(n[26]=o("p",null,"從 URL 下載文件，複製 URL 並打開 Tor 瀏覽器並粘貼。打開 URL 並下載文件/文件夾。",-1)),o("p",null,[r(e,{href:"http://www.theitstuff.com/wp-content/uploads/2017/12/Tor.png"},{default:a(()=>[...n[8]||(n[8]=[o("img",{src:"http://www.theitstuff.com/wp-content/uploads/2017/12/Tor.png",alt:"receive file with onionshare anonymously"},null,-1)])]),_:1})]),n[27]||(n[27]=i('<h3 id="onionshare-的起源" tabindex="-1">OnionShare 的起源 <a class="header-anchor" href="#onionshare-的起源" aria-label="Permalink to “OnionShare 的起源”">​</a></h3><p>幾年前，Glenn Greenwald 發現他從 Edward Snowden 收到的一些 NSA 的文件已經被損壞。但他需要該文件，並決定通過使用 USB 獲取那些文件。這並不成功。</p><p>在閲讀了 Greenwald 寫的書後，The Intercept 的安全專家 Micah Lee 發佈了 OnionShare —— 一個簡單的免費軟件，可以匿名和安全地共享文件。他創建了一個程序，通過一個被匿名軟件 Tor 加密和保護的直接通道來分享大型數據轉儲，使竊取者難以獲取文件。</p><h3 id="onionshare-如何工作" tabindex="-1">OnionShare 如何工作？ <a class="header-anchor" href="#onionshare-如何工作" aria-label="Permalink to “OnionShare 如何工作？”">​</a></h3><p>OnionShare 在 127.0.0.1 上啓動了一個 Web 服務器，用於在隨機端口上共享文件。它從有 6880 個單詞的單詞列表中選擇任意兩個單詞，稱為 slug。它使服務器可以作為 Tor 洋葱服務發送文件。最終的 URL 看起來像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>http://qx2d7lctsnqwfdxh.onion/subside-durable</span></span></code></pre></div><p>OnionShare 在下載後關閉。有一個選項允許多次下載文件。這使得該文件在互聯網上不能再次得到。</p><h3 id="使用-onionshare-好處" tabindex="-1">使用 OnionShare 好處 <a class="header-anchor" href="#使用-onionshare-好處" aria-label="Permalink to “使用 OnionShare 好處”">​</a></h3><p>其他網站或程序可以訪問你的文件：發件人使用 OnionShare 共享的文件不存儲在任何服務器上。它直接託管在發件人的系統上。</p><p>沒有人可以窺探共享文件：由於用户之間的連接是由洋葱服務和 Tor 瀏覽器加密的。這使得連接安全，很難竊取文件。</p><p>用户雙方都是匿名的：OnionShare 和 Tor 瀏覽器使發件人和收件人匿名。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>在這篇文章中，我已經解釋瞭如何<strong>匿名分享你的文檔、文件</strong>。我也解釋了它是如何工作的。希望你瞭解 OnionShare 是如何工作的，如果你對任何事情仍有疑問，只需留言。</p><hr>',14)),o("p",null,[n[10]||(n[10]=t("via: ",-1)),r(e,{href:"https://www.theitstuff.com/onionshare-share-files-anonymously-2"},{default:a(()=>[...n[9]||(n[9]=[t("https://www.theitstuff.com/onionshare-share-files-anonymously-2",-1)])]),_:1})]),o("p",null,[n[14]||(n[14]=t("作者：",-1)),r(e,{href:"https://www.theitstuff.com"},{default:a(()=>[...n[11]||(n[11]=[t("Anirudh Rayapeddi",-1)])]),_:1}),n[15]||(n[15]=t(" 譯者：",-1)),r(e,{href:"https://github.com/geekpi"},{default:a(()=>[...n[12]||(n[12]=[t("geekpi",-1)])]),_:1}),n[16]||(n[16]=t(" 校對：",-1)),r(e,{href:"https://github.com/wxy"},{default:a(()=>[...n[13]||(n[13]=[t("wxy",-1)])]),_:1})]),o("p",null,[n[19]||(n[19]=t("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...n[17]||(n[17]=[t("LCTT",-1)])]),_:1}),n[20]||(n[20]=t(" 原創編譯，",-1)),r(e,{href:"https://linux.cn/"},{default:a(()=>[...n[18]||(n[18]=[t("Linux中國",-1)])]),_:1}),n[21]||(n[21]=t(" 榮譽推出",-1))])])}const y=s(d,[["render",u]]);export{b as __pageData,y as default};
